// Verified against the local RED Corebook v1.22 and the publisher's v1.25 errata.
// Existing file IDs and canonical item keys preserve favorites and prepared stock.
const { category, labels: coreRuleLabels } = createRuleCatalog('red', 'Cyberpunk RED · Core Rulebook (v1.22 + errata v1.25)');
export { coreRuleLabels };
const failureRows = [
  [b('1 natural', 'Natural 1'), b('Resta otro 1d10 a STAT + habilidad + el primer 1. No repitas críticos del segundo dado. El resultado puede ser negativo y el intento todavía puede tener éxito.', 'Subtract another 1d10 from STAT + Skill + the original 1. The second die does not trigger another critical. The result may be negative and the Check may still succeed.')],
  [b('Sin tabla de pifias', 'No fumble table'), b('RED no añade una tabla de 1d6 de accidentes. Una arma de mala calidad se atasca con un 1 natural y requiere una acción para desatascarla.', 'RED adds no d6 mishap table. A Poor Quality weapon jams on a natural 1 and requires an Action to clear.')],
];
const combatGeneral: RuleFile[] = [
  { key: 'initiativeTurnOrder', title: b('Iniciativa y turno', 'Initiative and turn order'), pages: '168–169', description: b('RED · asaltos de unos 3 segundos. La iniciativa no es una prueba de habilidad.', 'RED · rounds last about 3 seconds. Initiative is not a Skill Check.'), rows: [
    [b('Iniciativa', 'Initiative'), b('REF + 1d10; de mayor a menor. Los empates se vuelven a tirar. Los solos pueden aplicar Initiative Reaction.', 'REF + 1d10, descending order. Reroll ties. Solos may apply Initiative Reaction.')],
    [b('Turno', 'Turn'), b('Una acción de movimiento y otra acción. Puedes intercalar el movimiento con la acción y con los dos ataques de fuentes ROF 2.', 'One Move Action and one other Action. Movement may be split around the Action and the two attacks of ROF 2 sources.')],
    [b('Movimiento', 'Movement'), b('MOVE × 2 m (MOVE casillas). Correr añade otro movimiento, después del primero. Nadar, escalar o saltar con carrerilla cuestan el doble; desde parado saltas la mitad.', 'MOVE × 2 m/yd (MOVE squares). Run adds another Move after the first. Swimming, climbing and running jumps cost double movement; standing jumps cover half the distance.')],
  ] },
  { key: 'combatActions', title: b('Acciones de combate disponibles', 'Available Combat Actions'), pages: '168–177', description: b('RED · una acción por turno, además del movimiento. Consulta la referencia específica para cada modalidad de ataque.', 'RED · one Action per turn, in addition to movement. Consult each attack mode’s own reference.'), rows: [
    [b('Atacar', 'Attack'), b('Hasta dos ataques de fuentes ROF 2, incluso distintas; una fuente ROF 1 consume toda la acción. Empates favorecen al defensor.', 'Up to two attacks from ROF 2 sources, including different sources; a ROF 1 source takes the whole Action. Ties favor the defender.')],
    [b('Disparo apuntado', 'Aimed Shot'), b('ROF 1, −8; cabeza, objeto en la mano o pierna. No con ráfaga ni cartuchos de perdigones.', 'ROF 1, −8; head, held item or leg. Not with Autofire or Shotgun Shells.')],
    [b('Fuego de supresión', 'Suppressive Fire'), b('10 balas; enfrenta REF + Autofire a WILL + Concentración. Consulta la tabla de supresión.', '10 bullets; oppose REF + Autofire to WILL + Concentration. See Suppressive Fire.')],
    [b('Agarrar / escapar', 'Grab / escape'), b('DEX + Pelea enfrentada a DEX + Pelea. Requiere mano libre para iniciar. Ambos sufren −2; el defensor no puede moverse por sí mismo.', 'DEX + Brawling vs DEX + Brawling. A free hand is required to initiate. Both take −2; the defender cannot move independently.')],
    [b('Estrangular / arrojar', 'Choke / throw'), b('Requiere ser el atacante de un agarre. Acción: BODY de daño directo a PV, sin ablación. Estrangular tres asaltos seguidos deja inconsciente; daño de >1 PV a <0 PV deja a 1 PV inconsciente. Arrojar termina el agarre y deja al objetivo en el suelo.', 'Requires being the attacker in a Grapple. Action: BODY direct HP damage, no ablation. Choking for three successive Rounds causes unconsciousness; damage from >1 HP to <0 HP leaves 1 HP and unconscious. Throwing ends Grapple and leaves target Prone.')],
    [b('Recargar', 'Reload'), b('Sustituye el cargador con un solo tipo de munición. Los arcos y ballestas no necesitan esta acción.', 'Replace the magazine with one ammunition type. Bows and Crossbows do not require this Action.')],
    [b('Mantener acción', 'Hold Action'), b('Retrasa una acción hasta una posición posterior de la cola de iniciativa; no permite retrasar movimiento ni acciones NET.', 'Delay an Action until later in the Initiative Queue; Move Actions and NET Actions cannot be held.')],
    [b('Correr / levantarse', 'Run / Get Up'), b('Correr: movimiento adicional después del normal. En el suelo no puedes realizar movimiento hasta usar Levantarse.', 'Run: extra movement after the normal Move. While Prone, no Move Action until Get Up.')],
    [b('Usar objeto / habilidad', 'Use an Object / Skill'), b('Guardar un arma cuesta acción; sacar un arma accesible a una mano libre o soltarla no. Equipar o soltar un escudo sí cuesta acción.', 'Stowing a weapon costs an Action; drawing an accessible weapon into a free hand or dropping it does not. Equipping or dropping a shield does cost an Action.')],
    [b('NET / vehículo / estabilizar', 'NET / vehicle / stabilize'), b('Usar las acciones NET disponibles, entrar o arrancar un vehículo, realizar una maniobra o estabilizar. Consulta sus referencias.', 'Use available NET Actions, enter or start a vehicle, perform a maneuver or stabilize. See their references.')],
  ] },
  { key: 'combatModifiers', title: b('Modificadores a pruebas', 'Check modifiers'), pages: '130, 170–172', description: b('RED · los modificadores pertinentes se acumulan. No hay bonificación genérica de emboscada ni penalizador de cobertura parcial.', 'RED · relevant modifiers are cumulative. There is no generic ambush bonus or partial-cover penalty.'), headers: [b('Situación', 'Situation'), b('Modificador / resolución', 'Modifier / resolution')], rows: [
    [b('Luz baja / primera vez', 'Low light / first attempt'), '−1'],
    [b('Complejidad, herramientas inadecuadas, mal descanso o estrés extremo', 'Complexity, inadequate tools, poor sleep or extreme stress'), '−2'],
    [b('Agotamiento, intoxicación extrema, actuar en secreto o tarea oculta por humo/oscuridad', 'Exhaustion, extreme intoxication, acting secretly or task obscured by smoke/darkness'), '−4'],
    [b('Disparo apuntado', 'Aimed Shot'), '−8'],
    [b('Objetivo que no advierte el ataque', 'Target unaware of the attack'), b('No puede esquivarlo. Un ataque cuerpo a cuerpo acierta automáticamente; a distancia usa la DV de alcance.', 'Cannot dodge. A Melee Attack hits automatically; a Ranged Attack uses the range DV.')],
    [b('Cobertura', 'Cover'), b('Bloquea la línea de visión. No aplica un −4 genérico al ataque: primero destruye la cobertura o consigue otra línea de tiro.', 'Blocks line of sight. It does not apply a generic −4 to attacks: destroy the cover or find another firing line.')],
  ] },
  { key: 'coverConcealment', title: b('Cobertura · PV y grosor', 'Cover · HP and thickness'), pages: '182–185', description: b('RED · cobertura completa que bloquea la línea de visión; no existe cobertura parcial. PV por sección de 2 × 2 m. A 0 PV se destruye; el daño sobrante se pierde salvo explosivos. Son PV, no SP.', 'RED · full cover blocks line of sight; no partial cover. HP per 2 × 2 m/yd section. At 0 HP it is destroyed; excess damage is lost except for explosives. These are HP, not SP.'), headers: [b('Material', 'Material'), b('Fina · PV', 'Thin · HP'), b('Gruesa · PV', 'Thick · HP')], rows: [
    [b('Acero', 'Steel'), 25, 50], [b('Piedra', 'Stone'), 20, 40], [b('Cristal antibalas', 'Bulletproof glass'), 15, 30], [b('Hormigón', 'Concrete'), 10, 25], [b('Madera', 'Wood'), 5, 20], [b('Yeso / espuma / plástico', 'Plaster / foam / plastic'), 0, 15],
  ] },
  { key: 'woundStateEffects', title: b('Estados de heridas', 'Wound states'), pages: '186–188', description: b('RED · los efectos del estado actual sustituyen a los del anterior. Un personaje herido mortalmente sigue consciente salvo que otra regla lo impida.', 'RED · the current state replaces the previous state’s effects. A Mortally Wounded character remains conscious unless another rule prevents it.'), headers: [b('Estado', 'State'), b('PV', 'HP'), b('Efecto', 'Effect')], rows: [
    [b('Leve', 'Lightly Wounded'), b('Por encima de la mitad', 'Above half'), b('Sin penalización.', 'No penalty.')],
    [b('Grave', 'Seriously Wounded'), b('Mitad o menos, pero más de 0', 'Half or less, but above 0'), b('−2 a todas las pruebas.', '−2 to all Checks.')],
    [b('Mortal', 'Mortally Wounded'), 0, b('−4 a todas las pruebas; MOVE −6 (mínimo 1). Salvación de muerte al inicio del turno. Daño de ataques posteriores causa una lesión crítica y +1 al penalizador de muerte.', '−4 to all Checks; MOVE −6 (minimum 1). Death Save at the start of the Turn. Damage from further attacks causes a Critical Injury and +1 Death Save Penalty.')],
    [b('Muerto', 'Dead'), '—', b('Una salvación de muerte fallida.', 'One failed Death Save.')],
  ] },
  { key: 'deathSaves', title: b('Salvaciones de muerte', 'Death Saves'), pages: '188, 222', description: b('RED · no es BODY + 1d10 contra una DV. No usa Suerte ni críticos de habilidad.', 'RED · not BODY + 1d10 against a DV. No LUCK or Skill Check critical rules.'), rows: [
    [b('Tirada', 'Roll'), b('Al inicio de cada turno herido mortalmente: 1d10 + penalizador actual. Sobrevives si el resultado es inferior a BODY; un 10 natural siempre falla.', 'At the start of every Mortally Wounded Turn: 1d10 + current penalty. Survive if the result is below BODY; a natural 10 always fails.')],
    [b('Acumulación', 'Accumulation'), b('Cada salvación aumenta en 1 el penalizador de las siguientes. Algunas lesiones y recibir daño con 0 PV lo incrementan también.', 'Each save adds 1 to the penalty on later saves. Certain injuries and damage at 0 HP also increase it.')],
    [b('Estabilización', 'Stabilization'), b('Devuelve a 1 PV. Elimina el penalizador acumulado por las tiradas, conservando el penalizador base de lesiones sin tratar.', 'Returns the character to 1 HP. Removes the penalty accumulated from rolling saves, retaining the base penalty from untreated injuries.')],
  ] },
  { key: 'armorAblation', title: b('Armadura y ablación', 'Armor and ablation'), pages: '97, 140, 186', description: b('RED · cabeza y cuerpo llevan SP independientes; usa solo el SP mayor. La ablación reduce todas las piezas de esa localización, sin sumar sus SP.', 'RED · head and body have separate SP; use only the highest SP. Ablation reduces all armor pieces at that location, without adding their SP.'), rows: [
    [b('Daño', 'Damage'), b('Resta SP al daño. Solo si pasa daño a PV, reduce en 1 el SP de la localización. La munición perforante reduce 2 en total.', 'Subtract SP from damage. Only if damage reaches HP, reduce that location’s SP by 1. Armor-Piercing Ammunition reduces it by 2 total.')],
    [b('Cuerpo a cuerpo', 'Melee'), b('Armas cuerpo a cuerpo y artes marciales usan la mitad de SP, redondeando hacia arriba. Pelea no lo reduce.', 'Melee Weapons and Martial Arts use half SP, rounded up. Brawling does not halve SP.')],
    [b('Reparar', 'Repair'), b('Basic Tech según la categoría de precio; consulta Reparaciones para DV y tiempo.', 'Basic Tech by price category; see Repairs for DV and time.')],
  ] },
  {key:'itemRepair',title:b('Reparaciones · DV y tiempo','Repairs · DV and time'),pages:'140',description:b('TECH + habilidad técnica apropiada. Fallo: a mitad del tiempo descubres que debes comenzar de nuevo. Armadura usa Basic Tech.','TECH + appropriate Tech Skill. Failure: halfway through the time, discover you must start over. Armor uses Basic Tech.'),headers:[b('Categoría / daño','Category / damage'),'headers.dv',b('Tiempo','Time')],rows:[['t:gear.cheap',9,b('1 hora','1 hour')],['t:gear.everyday',9,b('1 hora','1 hour')],['t:gear.costly',13,b('6 horas','6 hours')],['t:gear.premium',17,b('1 día','1 day')],['t:gear.expensive',21,b('1 semana','1 week')],['t:gear.veryExpensive',24,b('2 semanas','2 weeks')],['t:gear.luxury',29,b('1 mes','1 month')],['t:gear.superLuxury',29,b('1 mes por 10000 eb','1 month per 10000 eb')],[b('Vehículo · daño leve','Vehicle · minor damage'),9,b('3 horas','3 hours')],[b('Vehículo · daño grave','Vehicle · major damage'),13,b('1 día','1 day')],[b('Vehículo · destruido','Vehicle · destroyed'),17,b('1 semana','1 week')]]},
  { key: 'hpCalculation', title: b('PV y umbral de heridas', 'HP and wound threshold'), pages: '79', description: b('RED · PV máximos = 10 + 5 × redondear hacia arriba ((BODY + WILL) / 2). Herida grave a la mitad de los PV máximos, redondeando hacia arriba.', 'RED · maximum HP = 10 + 5 × round up ((BODY + WILL) / 2). Seriously Wounded at half maximum HP, rounded up.'), headers: ['headers.body', 'headers.will', 'headers.hp'], rows: [[2,2,20],[4,4,30],[4,6,35],[6,4,35],[6,6,40],[8,4,40],[6,8,45],[8,6,45],[8,8,50],[10,8,55],[8,10,55],[10,10,60]] },
];

